/* cppi::70f98601cad8ced566178a5d2d270e52753cb42e030c6d7b71f24437115381a5 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-11' and end_date = '2025-04-11')
and start_date = '2025-04-11' and end_date = '2025-04-11'

